'<tr><td style="padding:18px 26px 4px 26px;"><table width="100%" cellpadding="0" cellspacing="0"><tr>' +
'<td align="center" style="background:' + GREEN + ';border-radius:6px;padding:15px 6px;"><div style="color:#FFFFFF;font-family:Georgia,serif;font-size:26px;font-weight:bold;">' + offers.length + '</div><div style="color:#D6EBDD;font-size:10.5px;">offers out</div></td><td width="8"></td>' +
