  if (v === 'talent_pool' || v === 'not_progressing') { poolIds[cid] = true; if (!poolMeta[cid] || num(l.score) > num(poolMeta[cid].score)) { poolMeta[cid] = { score: num(l.score), role_id: rid }; } }
});
const splitList = (s) => String(s || '').toLowerCase().split(',').map(x => x.trim()).filter(x => x);
