const nice = splitList(role.good_to_have);
const budget = num(role.budget_ctc_lakh);
const stretch = 1 + (num(cfg.ctc_stretch_pct) || 15) / 100;
const minY = num(role.min_years); const maxY = num(role.max_years);
const roleLoc = String(role.location || '').toLowerCase().trim();
const maxNotice = num(role.notice_max_days) || 90;
const minScore = num(cfg.min_match_score) || 55;
const matches = [];
cands.forEach(c => {
  const cid = String(c.candidate_id).trim();
  if (!poolIds[cid] || alreadyThisRole[cid]) { return; }
  const skills = splitList(c.skills);
  const yrs = num(c.years_exp); const exp = num(c.expected_ctc_lakh); const notice = num(c.notice_days);
  const loc = String(c.location || '').toLowerCase().trim();
  let mustHit = 0; const missing = [];
  must.forEach(m => { if (skills.indexOf(m) !== -1) { mustHit += 1; } else { missing.push(m); } });
  let niceHit = 0;
  nice.forEach(m => { if (skills.indexOf(m) !== -1) { niceHit += 1; } });
  const why = [];
  let pts = Math.round((must.length ? mustHit / must.length : 1) * 40);
  if (mustHit === must.length) { why.push('has all ' + must.length + ' must haves for this role'); }
  else { why.push(mustHit + ' of ' + must.length + ' must haves, missing ' + missing.join(' and ')); }
  if (nice.length) { pts += Math.round((niceHit / nice.length) * 10); }
  if (yrs >= minY && yrs <= maxY) { pts += 20; why.push(yrs + ' years, inside the new band'); }
