return [{ json: { role_id: String(role.role_id), title: String(role.title), must_have: String(role.must_have || ''), budget_ctc_lakh: budget, location: String(role.location || ''), min_years: minY, max_years: maxY, notes: String(role.notes || ''), matches: top, match_count: top.length, pool_size: Object.keys(poolIds).length, match_lines: lines, company_name: cfg.company_name, recruiter_email: cfg.hiring_manager_email } }];

